$ErrorActionPreference='Stop'
$repo='F:/JericoEngine/JericoEngine';$base=Join-Path $repo 'build/n0-validation/local-packages/expat-rev1-validation'
$freeze=Get-Content -Raw (Join-Path $repo 'build/n0-validation/local-packages/expat-audit/source-freeze-writer14.json')|ConvertFrom-Json
$inputs=@();foreach($i in $freeze.inputs){$h=(Get-FileHash -LiteralPath $i.path -Algorithm SHA256).Hash.ToLowerInvariant();$inputs += [ordered]@{path=[string]$i.path;sha256=$h;matchesFreeze=($h -eq [string]$i.sha256)}}
$guards=@();foreach($name in @('uri','unc','missing-archive','bad-hash','bad-url','tampered-archive','existing-sentinel','outside-build')){$p=Join-Path (Join-Path $base 'guards') "$name/result.json";if(!(Test-Path $p)){throw "Missing native guard result $name"};$g=Get-Content -Raw $p|ConvertFrom-Json;$guards += [ordered]@{case=$g.case;exitCode=$g.exitCode;elapsedSeconds=$g.elapsedSeconds;expectedDiagnostic=$g.expectedDiagnostic;diagnosticMatched=$g.diagnosticMatched;outputExists=$g.outputExists}}
$sentinelPath=Join-Path $base 'guards/existing-sentinel/output/keep.txt';$sentinel=[ordered]@{path=$sentinelPath;content=(Get-Content -Raw $sentinelPath);sha256=(Get-FileHash $sentinelPath -Algorithm SHA256).Hash.ToLowerInvariant()}
$outsidePath=Join-Path $repo 'cmake';$outside=[ordered]@{path=$outsidePath;preexisting=$true;isDirectory=(Test-Path -LiteralPath $outsidePath -PathType Container);diagnosticRefusedOutput=$guards[-1].diagnosticMatched;harnessNote='outputExists=true reflects the preexisting cmake source directory; the wrapper refused before creating output. Original guard runner incorrectly treated any existing target as newly created.'}
$source='F:/JericoEngine/Dependencies/archives/expat-e26a263aa9182d1e4552cd615857f0f61df3ba42.tar.gz'
$report=[ordered]@{freezeManifestSHA256=(Get-FileHash (Join-Path $repo 'build/n0-validation/local-packages/expat-audit/source-freeze-writer14.json') -Algorithm SHA256).Hash;frozenInputCount=$inputs.Count;allFrozenInputsMatch=(@($inputs|Where-Object{!$_.matchesFreeze}).Count -eq 0);frozenInputs=$inputs;sourceArchiveSHA256=(Get-FileHash $source -Algorithm SHA256).Hash.ToLowerInvariant();packageProducer=(Get-Content -Raw (Join-Path $base 'expat-producer-result.json')|ConvertFrom-Json);packageAudit=(Get-Content -Raw (Join-Path $base 'expat-package-audit.json')|ConvertFrom-Json);guardCount=$guards.Count;guards=$guards;existingOutputSentinel=$sentinel;outsideBuild=$outside;consumerReleaseCTest=(Select-String -Path (Join-Path $base 'expat-consumer-ctest-release.stdout.log') -Pattern '100% tests passed'|ForEach-Object{$_.Line});consumerDebugCTest=(Select-String -Path (Join-Path $base 'expat-consumer-ctest-debug.stdout.log') -Pattern '100% tests passed'|ForEach-Object{$_.Line});symlinkGuard='Not attempted: no unprivileged fixture was assigned.'}
$path=Join-Path $base 'expat-final-validation-summary.json';if(Test-Path $path){throw 'Refusing to overwrite final summary'};[IO.File]::WriteAllText($path,($report|ConvertTo-Json -Depth 9),[Text.UTF8Encoding]::new($false));Write-Output ($report|ConvertTo-Json -Compress -Depth 4)
